/* Local review companion. All content and interactions are demonstrations. */
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(label,id,cls='')=>`<a class="${cls}" href="#${esc(id)}">${esc(label)}</a>`;
const action=(a,primary=false)=>a?`<button class="${primary?'primary':''}" data-go="${esc(a[1])}">${esc(a[0])}</button>`:'';
const nav=[['01','项目空间'],['05','项目总览'],['07','项目设定'],['09','故事与剧本'],['13','制作方案'],['18','素材库'],['24','分段提示词'],['28','图文审阅'],['31','交付导出'],['33','任务中心'],['35','设置与服务']];
const visual=(i=0)=>`<div class="visual ${i===1?'portrait':i===2?'prop':''}"><span class="caption">构图示意 · 非生成素材</span></div>`;
function render(){const id=location.hash.slice(1)||'index',s=id==='image-task'?imageTaskScreen():SCREENS.find(x=>x.id===id);document.title=(s?s.title:'原型导览')+' · AI 导演工作台';let body='';
if(!s){body=`<div class="tagline">AI DIRECTOR WORKBENCH</div><h1>完整功能原型</h1><p class="muted">${SCREENS.length} 个页面与关键状态 · 深色桌面 Web · V2.1</p><div class="banner">这是原型演示。页面跳转可用；字段可临时编辑并保存到当前浏览器会话。操作不连接模型、文件系统或付费服务。</div><div class="screen-index">${SCREENS.map(x=>link(x.id+' · '+x.title,x.id)).join('')}</div>`;}
else{let content='';if(s.cards)content+=`<div class="grid">${s.cards.map((c,i)=>`<div class="card">${['home','gallery'].includes(s.type)?visual(i):''}<div class="card-body"><h3>${esc(c[0])}</h3><p class="muted">${esc(c[1])}</p><span class="chip">${esc(c[2])}</span><div class="actions">${action(['打开 →',c[3]])}</div></div></div>`).join('')}</div>`;
if(s.shotViews) content+=`<div class="shot-filmstrip">${s.shotViews.map(([view,caption])=>`<figure><canvas data-shot-view="${esc(view)}" width="640" height="360" aria-label="${esc(caption)}"></canvas><figcaption>${esc(caption)}</figcaption></figure>`).join('')}</div>`;
if(s.segmentSummary) content+=`<p class="panel">${esc(s.segmentSummary)}</p>`;
if(s.referenceItems) content+=s.referenceItems.map(([title,description])=>`<article class="panel"><h3>${esc(title)}</h3><p>${esc(description)}</p></article>`).join('');
if(s.referenceEvidence) content+=`<details class="panel"><summary>核对 S02 · 00:09 候选切点（预设示例）</summary>${s.referenceEvidence.map(line=>`<p>${esc(line)}</p>`).join('')}</details>`;
if(s.fields)content+=`<form class="panel" id="fields">${s.fields.map((f,i)=>`<label class="field"><span>${esc(f[0])}</span><textarea name="f${i}" rows="2">${esc(read('field:'+id+':'+i,f[1]))}</textarea><small>${esc(f[2])}</small></label>`).join('')}<button type="submit">保存本页输入（演示）</button></form>`;
if(s.type==='entity'||s.type==='shot'||s.type==='review')content+=visual(0);
if(s.text)content+=`<div class="editor" contenteditable="true" role="textbox" aria-label="正文原型编辑" data-editor="${esc(id)}">${esc(read('text:'+id,s.text))}</div><div class="toolbar"><button data-save-text="${esc(id)}">保存正文（演示）</button><small>仅保存在当前浏览器会话，不影响 Figma 或正式成果。</small></div>`;
if(s.old)content+=`<div class="split"><div class="panel"><h3>原采用版本</h3><p class="diff-old">${esc(s.old)}</p></div><div class="panel"><h3>待采用 / 新正式版本</h3><p class="diff-new">${esc(s.newText)}</p></div></div>`;
if(s.rows)content+=`<div class="table-wrap"><table><thead><tr>${(s.headers||['成果','状态','信息','操作']).map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${s.rows.map(r=>`<tr>${r.slice(0,3).map(x=>`<td>${esc(x)}</td>`).join('')}<td>${link('查看 →',r[3])}</td></tr>`).join('')}</tbody></table></div>`;
if(s.empty)content+=`<div class="empty"><div class="metric">◇</div><h2>${esc(s.empty[0])}</h2><p class="muted">${esc(s.empty[1])}</p>${action(s.action,true)}</div>`;
body=`<div class="breadcrumb">${link('原型导览','index')} / 末班渡轮 / ${esc(s.title)}</div><div class="titlebar"><div><h1>${esc(s.title)}</h1><span class="muted">${esc(s.subtitle)}</span></div><div class="actions">${action(s.secondary)}${action(s.action,true)}</div></div>${s.tabs?`<div class="tabs" aria-label="页签示意">${s.tabs.map((t,i)=>`<span class="${i?'muted':''}">${esc(t)}</span>`).join('')}</div>`:''}${s.banner?`<div class="banner warn">${esc(s.banner)}</div>`:''}<div class="two"><section>${content}</section><section><div class="panel">${s.dialogue?`<h3>导演助手</h3><p class="chip">你</p><p>${esc(s.dialogue[0])}</p><p class="chip">助手</p><p>${esc(s.dialogue[1])}</p>`:''}<h3>${esc(s.sideTitle)}</h3>${(s.side||[]).map(x=>`<p class="muted">${esc(x)}</p>`).join('')}<h3 style="margin-top:24px">相关操作</h3>${(s.links||[]).map(x=>`<p>${link(x[0]+' →',x[1])}</p>`).join('')}</div></section></div><details class="rules" open><summary>交互与验收说明</summary><ul>${(s.rules||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details><div class="footerline"><span>原型演示 · ${id==='image-task'?'图像批次':id+' / '+SCREENS.length}</span>${link('返回全部页面','index')}</div>`;}
document.querySelector('#app').innerHTML=`<header><div class="brand"><b>▰</b>AI 导演工作台</div><span class="prototype-note">功能原型 · 无真实生成或付费</span><div>${link('原型导览','index')}　 ${link('任务中心 ↗','33')}</div></header><div class="layout"><aside class="nav"><div class="project-switch"><strong>末班渡轮 ⌄</strong><p class="muted">单片 · 16:9 · 中文</p></div>${nav.map(([n,t])=>link(t,n,id===n?'active':'')).join('')}<div class="nav-foot">本地优先 · V2.1<br>示例内容用于设计评审</div></aside><main>${body}</main></div>`;
mountShotDiagrams();
mountModelPicker(id);
mountImagePicker(id);
document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{if(b.dataset.modelSubmit){const [provider,model,effort]=Array.from(document.querySelectorAll('.model-picker select'),c=>c.value);write('selection:last-submission',JSON.stringify({provider,model,effort}));}location.hash=b.dataset.go});document.querySelector('#fields')?.addEventListener('submit',e=>{e.preventDefault();new FormData(e.target).forEach((v,k)=>write('field:'+id+':'+k.slice(1),v));toast('已保存本页输入到浏览器会话（演示）');});document.querySelector('[data-save-text]')?.addEventListener('click',()=>{write('text:'+id,document.querySelector('[data-editor]').innerText);toast('已保存正文到浏览器会话（演示）');});window.scrollTo(0,0);}
function read(k,f){try{return sessionStorage.getItem(k)??f}catch{return f}}
function write(k,v){try{sessionStorage.setItem(k,v)}catch{toast('浏览器不允许会话存储，本次修改仅留在页面。')}}
function toast(t){const n=document.querySelector('#toast');n.textContent=t;n.style.display='block';setTimeout(()=>n.style.display='none',2400)}
addEventListener('hashchange',render);render();
